using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Models;
namespace RaceDay.Api.Data;
public class RaceDayContext(DbContextOptions<RaceDayContext> options) : DbContext(options)
{
 public DbSet<User> Users => Set<User>(); public DbSet<Event> Events => Set<Event>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<EventOrganiser> EventOrganisers => Set<EventOrganiser>(); public DbSet<Registration> Registrations => Set<Registration>(); public DbSet<Result> Results => Set<Result>(); public DbSet<EventRoute> Routes => Set<EventRoute>(); public DbSet<Weather> Weather => Set<Weather>();
 protected override void OnModelCreating(ModelBuilder b)
 {
  b.Entity<User>().ToTable("USER").HasKey(x=>x.UserID); b.Entity<User>().Property(x=>x.UserID).HasColumnName("UserID"); b.Entity<User>().Property(x=>x.FirstName).HasMaxLength(50).IsUnicode(false); b.Entity<User>().Property(x=>x.LastName).HasMaxLength(50).IsUnicode(false); b.Entity<User>().Property(x=>x.Email).HasMaxLength(100).IsUnicode(false); b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<User>().Property(x=>x.PasswordHash).HasMaxLength(255).IsUnicode(false); b.Entity<User>().Property(x=>x.Phone).HasMaxLength(20).IsUnicode(false); b.Entity<User>().Property(x=>x.Role).HasMaxLength(20).IsUnicode(false); b.Entity<User>().Property(x=>x.CreatedAt).HasDefaultValueSql("GETDATE()");
  b.Entity<Event>().ToTable("EVENT").HasKey(x=>x.EventID); b.Entity<Event>().Property(x=>x.EventName).HasColumnName("EventName").HasMaxLength(150).IsUnicode(false); b.Entity<Event>().Property(x=>x.EventDescription).HasColumnType("varchar(max)"); b.Entity<Event>().Property(x=>x.EventType).HasMaxLength(20).IsUnicode(false); b.Entity<Event>().Property(x=>x.StartLocation).HasMaxLength(150).IsUnicode(false); b.Entity<Event>().Property(x=>x.EndLocation).HasMaxLength(150).IsUnicode(false); b.Entity<Event>().Property(x=>x.Status).HasMaxLength(20).IsUnicode(false); b.Entity<Event>().Property(x=>x.CreatedAt).HasDefaultValueSql("GETDATE()");
  b.Entity<Category>().ToTable("CATEGORY").HasKey(x=>x.CategoryID); b.Entity<Category>().Property(x=>x.CategoryName).HasMaxLength(100).IsUnicode(false); b.Entity<Category>().Property(x=>x.CategoryType).HasMaxLength(50).IsUnicode(false); b.Entity<Category>().Property(x=>x.Gender).HasMaxLength(20).IsUnicode(false).HasDefaultValue("Open"); b.Entity<Category>().Property(x=>x.Distance).HasPrecision(6,2); b.Entity<Category>().Property(x=>x.Description).HasColumnType("varchar(max)"); b.Entity<Category>().HasIndex(x=>new{x.EventID,x.CategoryName}).IsUnique();
  b.Entity<EventOrganiser>().ToTable("EVENT_ORGANISER").HasKey(x=>x.EventOrganiserID); b.Entity<EventOrganiser>().Property(x=>x.RoleInEvent).HasMaxLength(20).IsUnicode(false); b.Entity<EventOrganiser>().HasIndex(x=>new{x.UserID,x.EventID}).IsUnique();
  b.Entity<Registration>().ToTable("REGISTRATION").HasKey(x=>x.RegistrationID); b.Entity<Registration>().Property(x=>x.PaymentStatus).HasMaxLength(20).IsUnicode(false); b.Entity<Registration>().Property(x=>x.PaymentReference).HasMaxLength(100).IsUnicode(false); b.Entity<Registration>().Property(x=>x.EntryFee).HasPrecision(10,2); b.Entity<Registration>().Property(x=>x.Status).HasMaxLength(20).IsUnicode(false); b.Entity<Registration>().HasIndex(x=>new{x.UserID,x.EventID}).IsUnique();
  b.Entity<Result>().ToTable("RESULT").HasKey(x=>x.ResultID); b.Entity<Result>().Property(x=>x.Pace).HasPrecision(6,2); b.Entity<EventRoute>().ToTable("ROUTE").HasKey(x=>x.RouteID); b.Entity<EventRoute>().Property(x=>x.Distance).HasPrecision(6,2); b.Entity<EventRoute>().Property(x=>x.RouteName).HasMaxLength(100).IsUnicode(false); b.Entity<EventRoute>().Property(x=>x.RouteDescription).HasColumnType("varchar(max)"); b.Entity<EventRoute>().Property(x=>x.MapURL).HasMaxLength(255).IsUnicode(false); b.Entity<EventRoute>().Property(x=>x.GPXFileUrl).HasMaxLength(255).IsUnicode(false);
  b.Entity<Weather>().ToTable("WEATHER").HasKey(x=>x.WeatherID); b.Entity<Weather>().Property(x=>x.TemperatureMin).HasPrecision(5,2); b.Entity<Weather>().Property(x=>x.TemperatureMax).HasPrecision(5,2); b.Entity<Weather>().Property(x=>x.Precipitation).HasPrecision(6,2); b.Entity<Weather>().Property(x=>x.WindSpeed).HasPrecision(6,2); b.Entity<Weather>().Property(x=>x.Conditions).HasMaxLength(100).IsUnicode(false); b.Entity<Weather>().Property(x=>x.Source).HasMaxLength(100).IsUnicode(false);
 }
}
